'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint8Array = require( '@stdlib/array/uint8' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var dmskmax = require( './../lib' );


// TESTS //

tape( 'main export is an object', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dmskmax, 'object', 'main export is an object' );
	t.end();
});

tape( 'the `ndarray` method has an arity of 7', function test( t ) {
	t.strictEqual( dmskmax.ndarray.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method computes the maximum value of a strided array according to a mask', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
	mask = new Uint8Array( [ 0, 0, 1, 0 ] );

	v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
	t.strictEqual( v, 2.0, 'returns expected value' );

	x = new Float64Array( [ 3.0, -4.0, 1.0 ] );
	mask = new Uint8Array( [ 0, 1, 0 ] );

	v = dmskmax.ndarray( x.length, x, 1, 0, mask, 1, 0 );
	t.strictEqual( v, 3.0, 'returns expected value' );

	t.end();
});

tape( 'the `ndarray` method supports an `x` stride', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		2.0,  // 0
		-3.0,
		-5.0, // 1
		7.0,
		6.0   // 2
	]);
	mask = new Uint8Array([
		0, // 0
		1, // 1
		0  // 2
	]);

	v = dmskmax.ndarray( 3, x, 2, 0, mask, 1, 0 );
	t.strictEqual( v, 6.0, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method supports an `x` offset', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);
	mask = new Uint8Array([
		0, // 0
		0, // 1
		0  // 2
	]);

	v = dmskmax.ndarray( 3, x, 2, 1, mask, 1, 0 );
	t.strictEqual( v, 6.0, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method supports a `mask` stride', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		2.0,  // 0
		-3.0, // 1
		-5.0  // 2
	]);
	mask = new Uint8Array([
		0, // 0
		1,
		0, // 1
		1,
		0  // 2
	]);

	v = dmskmax.ndarray( 3, x, 1, 0, mask, 2, 0 );
	t.strictEqual( v, 2.0, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method supports a `mask` offset', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		1.0, // 0
		2.0, // 1
		3.0  // 2
	]);
	mask = new Uint8Array([
		1,
		1,
		1,
		0, // 0
		1, // 1
		0  // 2
	]);

	v = dmskmax.ndarray( 3, x, 1, 0, mask, 1, 3 );
	t.strictEqual( v, 3.0, 'returns expected value' );
	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the `ndarray` method returns `NaN`', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array( [ 3.0, -4.0, 1.0 ] );
	mask = new Uint8Array( [ 0, 0, 0 ] );

	v = dmskmax.ndarray( 0, x, 1, 0, mask, 1, 0 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );

	v = dmskmax.ndarray( -4, x, 1, 0, mask, 1, 0 );
	t.strictEqual( isnan( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method supports negative strides', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		1.0, // 2
		2.0,
		3.0, // 1
		4.0,
		5.0  // 0
	]);
	mask = new Uint8Array([
		0, // 2
		1, // 1
		0  // 0
	]);

	v = dmskmax.ndarray( 3, x, -2, x.length-1, mask, -1, 2 );
	t.strictEqual( v, 5.0, 'returns expected value' );
	t.end();
});

tape( 'the `ndarray` method supports complex access patterns', function test( t ) {
	var mask;
	var v;
	var x;

	x = new Float64Array([
		1.0, // 0
		2.0,
		3.0, // 1
		4.0,
		5.0  // 2
	]);
	mask = new Uint8Array([
		1, // 2
		0, // 1
		0  // 0
	]);

	v = dmskmax.ndarray( 3, x, 2, 0, mask, -1, mask.length-1 );
	t.strictEqual( v, 3.0, 'returns expected value' );
	t.end();
});
